function Paper({id,title,children,className='',x,y,reset,raise}:{id:string,title:string,children:ReactNode,className?:string,x:number,y:number,reset:number,raise:()=>number}){
 const [pos,setPos]=useState({x,y});const [z,setZ]=useState(1);const active=useRef<{x:number,y:number,left:number,top:number}|null>(null);
 useEffect(()=>{setPos({x,y});setZ(1)},[reset,x,y]);
 function constrain(el:HTMLElement,a:number,b:number){const board=el.closest('.desk')!;const card=el.parentElement!;return{x:Math.max(0,Math.min(board.clientWidth-card.clientWidth,a)),y:Math.max(0,Math.min(board.clientHeight-card.clientHeight,b))}}
 function start(e:PointerEvent<HTMLDivElement>){if(e.button!==0)return;setZ(raise());active.current={x:e.clientX,y:e.clientY,left:pos.x,top:pos.y};e.currentTarget.setPointerCapture(e.pointerId)}
 return <article id={`paper-${id}`} className={'paper '+className} style={{left:pos.x,top:pos.y,zIndex:z}} onPointerDown={()=>setZ(raise())}><div className="dragbar" role="button" tabIndex={0} aria-label={`拖动${title}，也可使用方向键移动`} onPointerDown={start} onPointerMove={e=>{if(active.current){const a=active.current;setPos(constrain(e.currentTarget,a.left+e.clientX-a.x,a.top+e.clientY-a.y))}}} onPointerUp={()=>active.current=null} onPointerCancel={()=>active.current=null} onKeyDown={e=>{const d:Record<string,number[]>={ArrowLeft:[-20,0],ArrowRight:[20,0],ArrowUp:[0,-20],ArrowDown:[0,20]};if(d[e.key]){e.preventDefault();setZ(raise());setPos(constrain(e.currentTarget,pos.x+d[e.key][0],pos.y+d[e.key][1]))}}}><span>{id} / {title}</span><span aria-hidden="true">⠿</span></div>{children}</article>
}
