Object.assign(works[1],{name:'境水 AquaMirror',en:'AQUAMIRROR',type:'交互影像 / 装置设计',year:'—',desc:'《境水 AquaMirror》是一件以敦煌藻井与水波为视觉线索的交互影像装置。项目探索将多人呼吸与生理状态转译为生成式光影，通过水面、投影和空间中的共同观看，呈现个体与群体之间的联系。',cover:'/preview-cover-2.jpg',real:true});
Object.assign(works[2],{name:'漂流者 The Castaway',en:'THE CASTAWAY',type:'展览策划 / 交互装置',year:'2026',desc:'《漂流者 The Castaway》是一项结合漂流仪式、实时影像、交互装置与个人记忆的场域特定展览方案。项目设想通过九个透明容器与黄河支流建立联系，以影像、声音和漂流轨迹探索河流的不可见性、不可预测性与生态记忆。',cover:'/preview-cover-3.jpg',real:true});
Object.assign(works[3],{name:'织隐',en:'STITCHING THE INVISIBLE',type:'参与式设计 / 数据刺绣',year:'2026',desc:'《织隐 Stitching the Invisible》探索以刺绣记录身体经验的设计方法。通过色彩、针脚密度与花卉纹样，将劳动、疼痛与个人记忆转化为可以触摸和讲述的实体数据，并以绣迹 XiuTrace 交互系统连接刺绣、身体可视化与口述故事。',cover:'/preview-cover-4.jpg',real:true});
Object.assign(works[4],{name:'预言 Prediction',en:'PREDICTION',type:'交互影像 / 装置艺术',year:'2024',desc:'《预言 Prediction》结合交互影像、铁磁流体与热敏打印，探索语言、人工智能与物质形态之间的关系。作品以脑电信号、生成式回应和电磁控制为线索，将抽象信息转化为流体形态、投影与纸面符号，构建一种关于未来语言的装置体验。',cover:'/preview-cover-5.jpg',real:true});
Object.assign(works[5],{name:'沙丘 Dune',en:'DUNE',type:'交互装置 / 环境议题',year:'—',desc:'《沙丘 Dune》以城市热岛与人与自然的关系为线索，将观众数量转化为装置中的热量变化。摄像头检测到的人脸数量经由 Arduino 控制继电器与加热灯，使金属城市模型逐渐融化，以物质形态的变化呈现人口、城市发展与环境之间的联系。',cover:'/preview-cover-6.jpg',real:true});
Object.assign(works[6],{name:'共生 Intergrowth',en:'INTERGROWTH',type:'展馆设计 / 交互装置',year:'—',desc:'《共生 Intergrowth》以“天人合一”为概念，探索人与植物、空间及生态循环之间的关系。展馆方案将植物、肥料、阳光与集雨四组装置和餐厅相连，通过观众参与、水与养分的循环以及生长影像，呈现相互依存的生命系统。',cover:'/preview-cover-7.jpg',real:true});
Object.assign(works[7],{name:'螺旋',en:'SPIRAL',type:'虚拟空间 / 交互设计',year:'—',desc:'《螺旋》以“沉默的螺旋”为概念起点，探索群体意见、话语权与虚拟空间之间的关系。方案将不同立场转译为数字形态，并设想通过可穿戴设备的位置映射，让用户的靠近、聚集与分离改变虚拟空间中的图像关系。',cover:'/preview-cover-8.jpg',real:true});
Object.assign(works[8],{name:'解码',en:'DECODE',type:'交互装置 / 数据可视化',year:'—',desc:'《解码》是一项结合生理信号、曼陀罗图像与音乐交互的艺术装置设计。作品以心跳等数据为创作线索，探索将身体节奏转译为图形、可视化页面与纸带乐谱，为自我观察和情绪表达提供感官体验。',cover:'/preview-cover-9.jpg',real:true});
Object.assign(works[9],{name:'独行',en:'LONE',type:'代际设计 / 游戏设计',year:'—',desc:'《独行》是一项关注独居、孤独与代际沟通的游戏及可穿戴设计方案。作品将孤独经验转化为循环的楼梯、无法打开的门与不断变化的空间，设想通过易于参与的游戏交互连接不同年龄的玩家，唤起对独居人群的关注。',cover:'/preview-cover-10.jpg',real:true});
Object.assign(works[10],{name:'手语',en:'SIGN LANGUAGE',type:'交互装置 / 非语言沟通',year:'—',desc:'《手语》是一件围绕手势、书写与非语言沟通展开的交互装置作品。设计结合机械臂、毛笔与手势交互，将身体动作与书写动作相联系，探索声音之外的表达方式，并邀请观众关注不同人群的沟通体验。',cover:'/preview-cover-11.jpg',real:true});
Object.assign(works[11],{name:'冬奥会开幕式美术设计',en:'WINTER OLYMPICS',type:'实践项目 / 美术设计',year:'—',desc:'北京冬奥会开幕式美术设计参与项目。作为项目参与者之一，参与中国纹样的设计与视觉融合，探索传统花卉纹样在舞台影像中的呈现。作品档案收录纹样线稿、舞台全景与局部效果图。',cover:'/preview-cover-12.jpg',real:true});
Object.assign(works[12],{name:'最后一行',en:'THE LAST LINE',type:'互动机械装置 / 参与式艺术',year:'2026',desc:'《最后一行》源于艺术家为祖父办理死亡证明的经历。观众坐在覆着白布的桌前，用机械打字机为尚未发生的死亡填写一份证明。每一次落键，都将仍然活着的身体暂时转化为姓名、日期与死因等可以被归档的字段。作品通过机械书写、纸张堆叠与观众参与，追问：我们看见的是一个人，还是一组信息？',cover:'/lastline/cover-thumb.jpg',real:true});
