function Booklet({pages=bookPages,pdf="/tao/booklet.pdf",title="一方洮砚，一方山水",aspect=1.03}:{pages?:{src:string}[],pdf?:string,title?:string,aspect?:number}){
 const pageCount=pages.length;const lastSpread=Math.ceil(pageCount/2)-1;
 const left=(s:number)=>s*2+1;const right=(s:number)=>s*2+2;
 const [spread,setSpread]=useState(0);const [turn,setTurn]=useState<1|-1|0>(0);const swipe=useRef<number|null>(null);
 useEffect(()=>{if(!turn)return;const t=setTimeout(()=>{setSpread(s=>s+turn);setTurn(0)},720);return()=>clearTimeout(t)},[turn]);
 function flip(d:1|-1){if(turn||spread+d<0||spread+d>lastSpread)return;setTurn(d)}
 const page=(n:number,side:string)=><div className={`book-page ${side}`}>{n>0&&n<=pageCount?<img src={pages[n-1].src} alt={`小册子第 ${n} 页`} draggable={false}/>:<div className="book-endpaper">{title}</div>}</div>;
 const target=spread+turn;
 return <div className="physical-book"><div className="book-spread" style={{aspectRatio:aspect}} role="group" aria-label="小册子，点击左右书页或左右滑动翻页" tabIndex={0} onKeyDown={e=>{if(e.key==='ArrowRight'){e.preventDefault();flip(1)}if(e.key==='ArrowLeft'){e.preventDefault();flip(-1)}}} onPointerDown={e=>swipe.current=e.clientX} onPointerUp={e=>{if(swipe.current!==null){const dx=e.clientX-swipe.current;swipe.current=null;if(Math.abs(dx)>35){flip(dx<0?1:-1);return}const rect=e.currentTarget.getBoundingClientRect();flip(e.clientX<rect.left+rect.width/2?-1:1)}}} onPointerCancel={()=>swipe.current=null}>
 {page(turn===-1?left(target):left(spread),'left')}{page(turn===1?right(target):right(spread),'right')}
 {turn!==0&&<div className={`turning-leaf ${turn===1?'forward':'backward'}`} key={`${spread}-${turn}`}><div className="leaf-front">{page(turn===1?right(spread):left(spread),'')}</div><div className="leaf-back">{page(turn===1?left(target):right(target),'')}</div></div>}<div className="book-spine"/>
 </div><div className="booklet-controls"><button disabled={spread===0||turn!==0} onClick={()=>flip(-1)} aria-label="上一跨页">←</button><span aria-live="polite">{left(spread)} — {Math.min(right(spread),pageCount)} / {pageCount}</span><button disabled={spread===lastSpread||turn!==0} onClick={()=>flip(1)} aria-label="下一跨页">→</button><a href={pdf} target="_blank" rel="noreferrer">完整 PDF ↗</a></div><p className="book-instruction">点击左右书页 / 左右滑动翻页 / 方向键翻页</p></div>
}
